import{_ as o,o as e,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Backup no Google Drive","description":"","frontmatter":{"title":"Backup no Google Drive"},"headers":[],"relativePath":"geral/backup-google-drive.md","filePath":"geral/backup-google-drive.md"}'),t={name:"geral/backup-google-drive.md"};function i(n,a,c,d,u,l){return e(),r("div",null,a[0]||(a[0]=[s('<h1 id="backup-no-google-drive" tabindex="-1">Backup no Google Drive <a class="header-anchor" href="#backup-no-google-drive" aria-label="Permalink to &quot;Backup no Google Drive&quot;">​</a></h1><p>Guarda cópias das suas configurações e dados do eploc na sua própria conta Google e, se você quiser, mantém vários computadores sincronizados. É <strong>opcional</strong> e vem <strong>desligado</strong>.</p><h2 id="como-funciona" tabindex="-1">Como funciona <a class="header-anchor" href="#como-funciona" aria-label="Permalink to &quot;Como funciona&quot;">​</a></h2><ul><li>Os backups ficam na <strong>pasta de dados do aplicativo</strong> do seu Google Drive (escopo <code>drive.appdata</code>): uma área oculta, reservada ao eploc, que não aparece entre seus arquivos. O eploc não tem acesso aos demais arquivos do seu Drive.</li><li>Cada envio cria um arquivo novo, com data e hora no nome. Nenhum backup é sobrescrito. Ficam os <strong>20 mais recentes</strong>; os mais antigos são apagados automaticamente.</li><li>O conteúdo é o mesmo do <a href="./backup-arquivo">backup em arquivo</a>.</li><li>Os dados vão direto do seu navegador para a sua conta Google. Não passam por servidor do desenvolvedor.</li></ul><h2 id="conectar" tabindex="-1">Conectar <a class="header-anchor" href="#conectar" aria-label="Permalink to &quot;Conectar&quot;">​</a></h2><ol><li>Configurações → aba <strong>Ajustes gerais e Backup</strong> → card <strong>Backup no Google Drive</strong>.</li><li>Ligue <strong>Habilitar backup no Google Drive</strong>.</li><li>Na janela do Google, escolha a conta e autorize o aplicativo <strong>eploc</strong>.</li><li>Se a conta já tiver backups do eploc, o eploc pergunta se você quer revisá-los e restaurar algum agora (<strong>Revisar backup</strong> ou <strong>Agora não</strong>).</li></ol><p>A autorização só é pedida na primeira conexão e quando você desconecta e conecta de novo.</p><h2 id="usar" tabindex="-1">Usar <a class="header-anchor" href="#usar" aria-label="Permalink to &quot;Usar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Botão ou opção</th><th>O que faz</th></tr></thead><tbody><tr><td>Fazer backup agora</td><td>Envia um backup na hora.</td></tr><tr><td>Restaurar o backup mais recente</td><td>Abre a revisão do backup mais recente para escolher o que restaurar.</td></tr><tr><td>Restaurar uma versão mais antiga</td><td>Lista os backups da conta. Cada um pode ser restaurado, baixado como arquivo ou excluído.</td></tr><tr><td>Procurar dados ausentes em backups antigos</td><td>Procura em backups antigos itens que sumiram do backup atual (por exemplo, um modelo apagado sem querer) e permite importá-los um a um.</td></tr><tr><td>Manter sincronizado automaticamente entre dispositivos</td><td>Envia as mudanças cerca de 1 minuto depois de acontecerem e verifica novidades dos outros computadores a cada 15 minutos, mais ou menos.</td></tr></tbody></table><h2 id="sincronizacao-entre-computadores" tabindex="-1">Sincronização entre computadores <a class="header-anchor" href="#sincronizacao-entre-computadores" aria-label="Permalink to &quot;Sincronização entre computadores&quot;">​</a></h2><p>Com a sincronização automática ligada em dois ou mais computadores (com a mesma conta Google conectada):</p><ul><li>os dados (contatos de e-mail, modelos de mensagem e modelo padrão, destaques, processos monitorados, pastas de preferências) são <strong>somados</strong>: o que é criado num computador aparece nos outros, e nada é apagado por causa da sincronização;</li><li>edições do mesmo item seguem a mais recente;</li><li>os interruptores e opções das funcionalidades <strong>não</strong> são sincronizados, porque podem ser escolhas diferentes em cada computador. Para levá-los, use <strong>Restaurar o backup mais recente</strong>.</li></ul><h2 id="desconectar" tabindex="-1">Desconectar <a class="header-anchor" href="#desconectar" aria-label="Permalink to &quot;Desconectar&quot;">​</a></h2><p>Desligue <strong>Habilitar backup no Google Drive</strong>. Os backups já enviados continuam na sua conta. Para apagá-los, exclua-os antes em <strong>Restaurar uma versão mais antiga</strong>. No próprio Google Drive, em Configurações → Gerenciar apps, também é possível excluir os dados ocultos do aplicativo eploc.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Se a autorização expirar, o ícone do eploc mostra um &quot;!&quot; laranja e o popup oferece <strong>Reconectar</strong>. Uma falha de rede passageira não desconecta a conta.</li><li>O valor anterior cifrado do Monitor de Relatórios nunca vai para o Drive.</li></ul>',16)]))}const g=o(t,[["render",i]]);export{m as __pageData,g as default};
